@staticmethod
def _validate_acceptance_fix_checks(
    checks_raw: Any,
    final_files: dict[str, str],
) -> tuple[list[dict[str, Any]], list[str]]:
    """Validiert echte satisfied:false-Checks gegen den finalen Dateistand."""
    validated: list[dict[str, Any]] = []
    problems: list[str] = []

    if not isinstance(checks_raw, list) or not checks_raw:
        return [], ["Acceptance-FIX_REQUIRED enthält keine strukturierten Checks."]

    for index, item in enumerate(checks_raw, 1):
        if not isinstance(item, dict):
            continue
        if item.get("satisfied") is not False:
            continue

        requirement = str(item.get("requirement", "")).strip()
        path = str(item.get("path", "")).strip()
        evidence = str(item.get("evidence", "")).strip()
        reason = str(item.get("reason", "")).strip()

        if not requirement or not path or not evidence or not reason:
            problems.append(
                f"Check {index} mit satisfied=false benötigt requirement, path, evidence und reason."
            )
            continue
        if path not in final_files:
            problems.append(
                f"{path}: satisfied=false verweist nicht auf eine geänderte finale Textdatei."
            )
            continue

        canonical_file = AgentController._canonical_evidence_text(final_files[path])
        canonical_evidence = AgentController._canonical_evidence_text(evidence)
        if not canonical_evidence or canonical_evidence not in canonical_file:
            problems.append(
                f"{path}: satisfied=false-Beleg ist im finalen Dateistand nicht vorhanden "
                f"(Anforderung: {shorten(redact(requirement), 180)}; "
                f"Beleg: {shorten(redact(evidence), 180)})."
            )
            continue

        validated.append({
            "requirement": shorten(redact(requirement), 500),
            "satisfied": False,
            "path": shorten(redact(path), 300),
            "evidence": shorten(redact(evidence), 700),
            "reason": shorten(redact(reason), 700),
        })

    if not validated and not problems:
        problems.append("Acceptance-FIX_REQUIRED enthält keinen satisfied=false-Check.")
    return validated, problems

